work_phase.pseudocode:
EXPORT FUNCTION buildUniversalPrompt(turnData, dimensionsArray): SET barsText = loop dimensionsArray to format "Dimension: [name]
L1: [..]
L2: [..]..." SET systemPrompt = LLM_PROMPT_CONTRACT.system_prompt SET userPrompt = "Question: {turnData.question}
Answer: {turnData.answer}
Evaluate:
{barsText}" RETURN { systemPrompt, userPrompt }
EXPORT FUNCTION evaluateWithUniversalLlm(turnData, dimensionsArray): SET prompt = buildUniversalPrompt(turnData, dimensionsArray) TRY SET response = CALL llm with schema RETURN parseAndScore(response, dimensionsArray) CATCH RETURN generateFallbackLevel1(dimensionsArray)
